from __future__ import annotations

from decimal import Decimal
from typing import Optional

FRACTION_TO_PERCENT = {
    '1/4': Decimal('25'),
    '1/2': Decimal('50'),
    '3/4': Decimal('75'),
    '1': Decimal('100'),
}


def resolve_consumed_percent(*, fraction: Optional[str], percent: Optional[float]) -> float:
    normalized = (fraction or '').strip()
    if normalized:
        if normalized not in FRACTION_TO_PERCENT:
            raise ValueError('FRACCION_CONSUMO_NO_PERMITIDA')
        if percent is not None:
            raise ValueError('CONSUMO_AMBIGUO_FRACCION_Y_PORCENTAJE')
        return float(FRACTION_TO_PERCENT[normalized])

    if percent is None:
        raise ValueError('CONSUMO_REQUIERE_FRACCION')

    value = float(percent)
    if value <= 0 or value > 100:
        raise ValueError('PORCENTAJE_CONSUMO_INVALIDO')
    return value

