import pytest

from modules.cava_socios.consumption_contract import resolve_consumed_percent


@pytest.mark.parametrize(
    ('fraction', 'expected'),
    [('1/4', 25.0), ('1/2', 50.0), ('3/4', 75.0), ('1', 100.0)],
)
def test_fraction_contract(fraction, expected):
    assert resolve_consumed_percent(fraction=fraction, percent=None) == expected


def test_percent_is_legacy_compatible_without_fraction():
    assert resolve_consumed_percent(fraction=None, percent=25) == 25.0


def test_requires_explicit_consumption():
    with pytest.raises(ValueError, match='CONSUMO_REQUIERE_FRACCION'):
        resolve_consumed_percent(fraction=None, percent=None)


def test_fraction_and_percent_cannot_be_mixed():
    with pytest.raises(ValueError, match='CONSUMO_AMBIGUO'):
        resolve_consumed_percent(fraction='1/4', percent=25)
